window.docContents[149].resolve({"/Elementary-Functions/___4___32-Inequalities/#chapter-4-section-32":{"contents":"Source: NIST Digital Library of Mathematical Functions, §4.32.\n\n\n\n","context":"LMLF · DLMF with Lean\u0009Elementary Functions","header":"4.32. §4.32 Inequalities","id":"/Elementary-Functions/___4___32-Inequalities/#chapter-4-section-32"},"/Elementary-Functions/___4___37-Inverse-Hyperbolic-Functions/#LMLF-___-DLMF-with-Lean--Elementary-Functions--___4___37-Inverse-Hyperbolic-Functions--___4___37-Inverse-Hyperbolic-Functions--Principal-values--4___37___1-___--Arcsinh-z____________dt_______LPAR_1___t____RPAR_-___-paths-avoid--___i-___":{"contents":"Source: DLMF 4.37.1\n\\mathrm{Arcsinh}z=\\int_{0}^{z}\\frac{dt}{\\sqrt{1+t^2}}.$$\n### 4.37.2 — Arccosh z=∫₁ᶻdt/√(t²−1), paths avoid ±1.\n\nSource: DLMF 4.37.2\n\\mathrm{Arccosh}z=\\int_{1}^{z}\\frac{dt}{\\sqrt{t^2-1}}.$$\n### 4.37.3 — Arctanh z=∫₀ᶻdt/(1−t²), z≠±1.\n\nSource: DLMF 4.37.3\n\\mathrm{Arctanh}z=\\int_{0}^{z}\\frac{dt}{1-t^2},\\qquad z\\ne\\pm1.$$\n### 4.37.4 — Arccsch z=Arcsinh(1/z), z≠0.\n\nSource: DLMF 4.37.4\n\\mathrm{Arccsch}z=\\mathrm{Arcsinh}\\left(1/z\\right).$$\n### 4.37.5 — Arcsech z=Arccosh(1/z), z≠0.\n\nSource: DLMF 4.37.5\n\\mathrm{Arcsech}z=\\mathrm{Arccosh}\\left(1/z\\right).$$\n### 4.37.6 — Arccoth z=Arctanh(1/z), z≠0 for the reciprocal encoding.\n\nSource: DLMF 4.37.6\n\\mathrm{Arccoth}z=\\mathrm{Arctanh}\\left(1/z\\right).$$\n### 4.37.7 — arccsch z=arcsinh(1/z), z≠0.\n\nSource: DLMF 4.37.7\n\\mathrm{arccsch}z=\\mathrm{arcsinh}\\left(1/z\\right).$$\n### 4.37.8 — arcsech z=arccosh(1/z), z≠0.\n\nSource: DLMF 4.37.8\n\\mathrm{arcsech}z=\\mathrm{arccosh}\\left(1/z\\right).$$\n### 4.37.9 — arccoth z=arctanh(1/z), z≠0, ±1.\n\nSource: DLMF 4.37.9\n\\mathrm{arccoth}z=\\mathrm{arctanh}\\left(1/z\\right),\\qquad z\\ne\\pm1.$$\n\n","context":"LMLF · DLMF with Lean\u0009Elementary Functions\u0009§4.37 Inverse Hyperbolic Functions\u0009§4.37 Inverse Hyperbolic Functions\u0009Principal values","header":"4.37.1 —  Arcsinh z=∫₀ᶻdt/√(1+t²) , paths avoid  ±i .","id":"/Elementary-Functions/___4___37-Inverse-Hyperbolic-Functions/#LMLF-___-DLMF-with-Lean--Elementary-Functions--___4___37-Inverse-Hyperbolic-Functions--___4___37-Inverse-Hyperbolic-Functions--Principal-values--4___37___1-___--Arcsinh-z____________dt_______LPAR_1___t____RPAR_-___-paths-avoid--___i-___"},"/Exponential___-Logarithmic___-Sine___-and-Cosine-Integrals/___6___10-Other-Series-Expansions/#chapter-6-section-10":{"contents":"Source: NIST Digital Library of Mathematical Functions, §6.10.\n\n\n\n","context":"LMLF · DLMF with Lean\u0009Exponential, Logarithmic, Sine, and Cosine Integrals","header":"6.10. §6.10 Other Series Expansions","id":"/Exponential___-Logarithmic___-Sine___-and-Cosine-Integrals/___6___10-Other-Series-Expansions/#chapter-6-section-10"},"/Gamma-Function/___5___5-Functional-Relations/#chapter-5-section-5":{"contents":"\n\n\n\n\n\n\n\n","context":"LMLF · DLMF with Lean\u0009Gamma Function","header":"5.5. §5.5 Functional Relations","id":"/Gamma-Function/___5___5-Functional-Relations/#chapter-5-section-5"}});